              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Fecha del Contrato de Crédito"
                  type="date"
                  value={fechaContrato}
                  onChange={(e) => setFechaContrato(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  required
                  size="small"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Días de Plazo"
                  type="number"
                  value={diasPlazo}
                  onChange={(e) => setDiasPlazo(Number(e.target.value))}
                  inputProps={{ min: 30, max: 180 }}
                  required
                  size="small"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Monto Total"
                  value={`$${montoTotal.toLocaleString()} COP`}
                  InputProps={{ readOnly: true }}
                  size="small"
                />
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      )}

      {/* Section 4: Anexo I Table */}
      {extractedData && (
        <Card sx={{ mb: 2 }}>
          <CardContent>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="subtitle1" fontWeight="medium">
                4. Anexo I - Detalle de Pagos
              </Typography>
              <Button startIcon={<AddIcon />} onClick={handleAddAnexoRow} size="small">
                Agregar Fila
              </Button>
            </Box>

            <TableContainer component={Paper} variant="outlined">
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Acreedor</TableCell>
                    <TableCell>No. Instrumento</TableCell>
                    <TableCell>Monto (COP)</TableCell>
                    <TableCell width={60}>Acción</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {anexoItems.map((item, index) => (
                    <TableRow key={index}>
                      <TableCell>
                        <TextField
                          fullWidth
                          value={item.acreedor}
                          onChange={(e) => handleAnexoItemChange(index, 'acreedor', e.target.value)}
                          size="small"
                          variant="standard"
                        />
                      </TableCell>
                      <TableCell>
                        <TextField
                          fullWidth
                          value={item.numeroInstrumento}
                          onChange={(e) => handleAnexoItemChange(index, 'numeroInstrumento', e.target.value)}
                          size="small"
                          variant="standard"
                        />
                      </TableCell>
                      <TableCell>
                        <TextField
                          fullWidth
                          type="number"
                          value={item.monto}
                          onChange={(e) => handleAnexoItemChange(index, 'monto', Number(e.target.value))}
                          size="small"
                          variant="standard"
                        />
                      </TableCell>
                      <TableCell>
                        <IconButton size="small" onClick={() => handleRemoveAnexoRow(index)} color="error">
                          <DeleteIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                  <TableRow>
                    <TableCell colSpan={2} align="right">
                      <strong>TOTAL:</strong>
                    </TableCell>
                    <TableCell colSpan={2}>
                      <strong>${montoTotal.toLocaleString()} COP</strong>
                    </TableCell>
                  </TableRow>
                </TableBody>
              </Table>
            </TableContainer>
          </CardContent>
        </Card>
      )}

      {/* Section 5: Submit */}
      {extractedData && (
        <Card>
          <CardContent>
            <Typography variant="subtitle1" gutterBottom fontWeight="medium">
              5. Generar Solicitud
            </Typography>

            <Button
              variant="contained"
              color="primary"
              onClick={handleSubmit}
              disabled={requesting || !selectedClient || !numeroCotizacion || !fechaContrato || anexoItems.length === 0}
              startIcon={requesting ? <CircularProgress size={20} /> : <CheckCircleIcon />}
              fullWidth
              size="large"
            >
              {requesting ? 'Generando...' : 'Solicitar Documento'}
            </Button>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

