                    '&:hover': { bgcolor: 'action.hover' },
                    bgcolor: selectedClient?.id === client.id ? 'action.selected' : 'inherit',
                  }}
                  onClick={() => setSelectedClient(client)}
                >
                  <CardContent sx={{ py: 1 }}>
                    <Typography variant="body1" fontWeight="medium">
