          {selectedClient && (
            <Box mt={2} p={2} bgcolor="success.lighter" borderRadius={1}>
              <Typography variant="body2" color="success.dark" fontWeight="medium">
                Cliente seleccionado: {selectedClient.nombre_importador} (NIT: {selectedClient.nit})
